static struct hpack_dht *hpack_dht_defrag(struct hpack_dht *dht)
{
        struct hpack_dht *alt_dht;
        uint16_t old, new;
        uint32_t addr;

        alt_dht = hpack_dht_alloc();
        if (!alt_dht)
                return NULL;

        alt_dht->total = dht->total;
        alt_dht->used = dht->used;
        alt_dht->wrap = dht->used;

        new = 0;
        addr = alt_dht->size;

        if (dht->used) {
                old = hpack_dht_get_tail(dht);
                do {
                        alt_dht->dte[new].nlen = dht->dte[old].nlen;
                        alt_dht->dte[new].vlen = dht->dte[old].vlen;
                        addr -= dht->dte[old].nlen + dht->dte[old].vlen;
                        alt_dht->dte[new].addr = addr;

                        memcpy((void *)alt_dht + alt_dht->dte[new].addr,
                               (void *)dht + dht->dte[old].addr,
                               dht->dte[old].nlen + dht->dte[old].vlen);

                        old++;
                        if (old >= dht->wrap)
                                old = 0;
                        new++;
                } while (new < dht->used);
        }

        alt_dht->front = alt_dht->head = new - 1;

        memcpy(dht, alt_dht, dht->size);
        hpack_dht_free(alt_dht);

        return dht;
}
```

The `memcpy((void *)alt_dht + alt_dht->dte[new].addr, (void *)dht + dht->dte[old].addr, dht->dte[old].nlen + dht->dte[old].vlen)` copies data from the old table to the new table. The source is `dht->dte[old].addr` and the length is `dht->dte[old].nlen + dht->dte[old].vlen`. 

The source `dht->dte[old].addr` is a valid data address in the old table. The length is the entry's data length. So the source read is within the old table. Safe.

The destination `alt_dht->dte[new].addr` is computed as `addr -= dht->dte[old].nlen + dht->dte[old].vlen`. Starting from `addr = alt_dht->size`, and subtracting each entry's data length. So the destination is within the new table. Safe.

