static inline struct ist hpack_alloc_string(struct buffer *store, uint32_t idx,
                                            struct ist in)
{
        struct ist out;

        if (idx < HPACK_SHT_SIZE)
                return in;

        out.len = in.len;
        out.ptr = chunk_newstr(store);
